static PyObject *encrypt(PyObject *self, PyObject *args){
    Py_buffer key, nonce, pt, aad;
    int has_aad = 0;
    if(!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)){
        /* try without aad */
        PyErr_Clear();
        if(!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
        has_aad = 0;
    } else {
        has_aad = (aad.buf != NULL);
    }
    const char *name = key.len==16?"AES-128-GCM": key.len==24?"AES-192-GCM":"AES-256-GCM";
    EVP_CIPHER *ciph = EVP_CIPHER_fetch(NULL, name, NULL);
    if(!ciph){ PyErr_SetString(PyExc_RuntimeError, "cipher fetch failed"); goto err; }
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if(!ct || !tag){ goto err2; }
    int outlen=0, tmplen=0;
    if(EVP_EncryptInit_ex(ctx, ciph, NULL, NULL, NULL)!=1) goto fail;
    if(EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL)!=1) goto fail;
    if(EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf)!=1) goto fail;
    if(has_aad && aad.len){
        if(EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len)!=1) goto fail;
    }
    if(EVP_EncryptUpdate(ctx, (unsigned char*)PyBytes_AS_STRING(ct), &outlen, pt.buf, (int)pt.len)!=1) goto fail;
    if(EVP_EncryptFinal_ex(ctx, (unsigned char*)PyBytes_AS_STRING(ct)+outlen, &tmplen)!=1) goto fail;
    if(EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, PyBytes_AS_STRING(tag))!=1) goto fail;
    EVP_CIPHER_CTX_free(ctx);
    EVP_CIPHER_free(ciph);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct, tag);
fail:
    PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
err2:
    EVP_CIPHER_CTX_free(ctx); EVP_CIPHER_free(ciph);
err:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return NULL;
}

