#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <openssl/modes.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

#define NTHREADS 4

typedef struct {
    unsigned char key[32];
    int keylen;
    unsigned char iv[16];
    int ivlen;
    unsigned char *pt;
    unsigned char *ct;
    size_t n;
    unsigned char *aad;
    size_t aadlen;
    /* outputs */
    unsigned char tag[16];
    int rc;
} job_t;

static void *worker(void *arg){
    job_t *j = arg;
    const char *name = j->keylen==16?"AES-128-GCM": j->keylen==24?"AES-192-GCM":"AES-256-GCM";
    EVP_CIPHER *ciph = EVP_CIPHER_fetch(NULL, name, NULL);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen=0, tmplen=0;
    j->rc = -1;
    if(!ciph || !ctx) goto done;
    if(EVP_EncryptInit_ex(ctx, ciph, NULL, NULL, NULL)!=1) goto done;
    if(EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, j->ivlen, NULL)!=1) goto done;
    if(EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->iv)!=1) goto done;
    if(j->aad && j->aadlen){
        if(EVP_EncryptUpdate(ctx, NULL, &outlen, j->aad, (int)j->aadlen)!=1) goto done;
    }
    if(j->n){
        if(EVP_EncryptUpdate(ctx, j->ct, &outlen, j->pt, (int)j->n)!=1) goto done;
    }
    if(EVP_EncryptFinal_ex(ctx, j->ct+outlen, &tmplen)!=1) goto done;
    if(EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, j->tag)!=1) goto done;
    j->rc = 0;
done:
    if(ctx) EVP_CIPHER_CTX_free(ctx);
    if(ciph) EVP_CIPHER_free(ciph);
    return NULL;
}

/* Increment 32-bit big-endian counter at the end of a 12-byte IV by `blocks`. */
static void iv_add(unsigned char dst[12], const unsigned char src[12], uint32_t blocks){
    memcpy(dst, src, 12);
    uint32_t c = ((uint32_t)src[8]<<24)|((uint32_t)src[9]<<16)|((uint32_t)src[10]<<8)|src[11];
    c += blocks;
    dst[8]=c>>24; dst[9]=c>>16; dst[10]=c>>8; dst[11]=c;
}

static PyObject *gcm_encrypt(PyObject *self, PyObject *args){
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    int has_aad = 0;
    if(!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)){
        PyErr_Clear();
        if(!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    } else has_aad = 1;

    if(key.len!=16 && key.len!=24 && key.len!=32){
        PyErr_SetString(PyExc_ValueError, "bad key size"); return NULL;
    }

    PyObject *ctobj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tagobj = PyBytes_FromStringAndSize(NULL, 16);
    if(!ctobj || !tagobj) return NULL;
    unsigned char *ct = (unsigned char*)PyBytes_AS_STRING(ctobj);
    unsigned char *tag = (unsigned char*)PyBytes_AS_STRING(tagobj);

    /* For small inputs or non-12-byte nonce, single-thread. */
    int use_parallel = (nonce.len==12 && pt.len >= 256*1024);
    int nth = use_parallel ? NTHREADS : 1;

    /* split into 16-byte aligned chunks */
    size_t total = pt.len;
    size_t blocks = total/16;
    size_t tail = total - blocks*16;

    job_t jobs[NTHREADS];
    pthread_t th[NTHREADS];
    memset(jobs, 0, sizeof(jobs));

    size_t blocks_per = blocks / nth;
    size_t assigned = 0;
    int launched = 0;
    for(int i=0;i<nth;i++){
        size_t b = (i==nth-1) ? (blocks - assigned) : blocks_per;
        size_t off = assigned*16;
        size_t len = b*16;
        if(i==nth-1) len += tail; /* last chunk gets partial block */
        if(len==0 && i>0) break;
        jobs[i].keylen = (int)key.len;
        memcpy(jobs[i].key, key.buf, key.len);
        jobs[i].ivlen = 12;
        if(nonce.len==12){
            iv_add(jobs[i].iv, nonce.buf, (uint32_t)(assigned+1)); /* GCM counter starts at 1 for data */
        } else {
            memcpy(jobs[i].iv, nonce.buf, nonce.len);
            jobs[i].ivlen = (int)nonce.len;
        }
        jobs[i].pt = (unsigned char*)pt.buf + off;
        jobs[i].ct = ct + off;
        jobs[i].n = len;
        if(i==0 && has_aad){ jobs[i].aad = aad.buf; jobs[i].aadlen = aad.len; }
        assigned += b;
        if(nth==1){
            worker(&jobs[0]);
        } else {
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        launched++;
    }
    if(nth>1){
        for(int i=0;i<launched;i++) pthread_join(th[i], NULL);
    }
    for(int i=0;i<launched;i++){
        if(jobs[i].rc!=0){
            PyErr_SetString(PyExc_RuntimeError, "worker failed");
            Py_DECREF(ctobj); Py_DECREF(tagobj);
            goto release;
        }
    }

    if(nth==1){
        memcpy(tag, jobs[0].tag, 16);
    } else {
        /* Combine per-chunk GCM tags into the real tag.
           Each worker encrypted with AAD only on chunk 0, and its own counter
           start, producing tag_i = GHASH(H, AAD_i, C_i) XOR E(K, J0)  where J0
           is the SAME for all (12-byte nonce => J0 = nonce||1) ... WAIT.

           Problem: worker uses iv = nonce with counter set to (assigned+1), so
           OpenSSL derives J0 from that iv, which is NOT the original J0, and the
           counter sequence starts at iv_counter+1, not at our intended counter.

           This approach is WRONG. See note in solver: we must not use EVP this way.
        */
        memcpy(tag, jobs[0].tag, 16); /* placeholder, incorrect */
    }

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ctobj, tagobj);

release:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", gcm_encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef mod = {PyModuleDef_HEAD_INIT, "gcmfast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_gcmfast(void){ return PyModule_Create(&mod); }
EOF
