#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <openssl/modes.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

#define NTHREADS 4

typedef struct {
    /* AES-CTR job */
    EVP_CIPHER_CTX *ctx;          /* prebuilt, key set, reused */
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned char iv[16];         /* full 16-byte counter block */
    int rc;
} ctr_job;

typedef struct {
    GCM128_CONTEXT *gctx;
    const unsigned char *data;
    size_t len;
    unsigned char hash[16];
    int rc;
} ghash_job;

static void *ctr_worker(void *arg){
    ctr_job *j = arg;
    int outlen = 0;
    j->rc = -1;
    if(EVP_EncryptInit_ex(j->ctx, NULL, NULL, NULL, j->iv) != 1) return NULL;
    if(EVP_EncryptUpdate(j->ctx, j->out, &outlen, j->in, (int)j->len) != 1) return NULL;
    j->rc = 0;
    return NULL;
}

static void *ghash_worker(void *arg){
    ghash_job *j = arg;
    unsigned char zeroes[16];
    memset(zeroes, 0, 16);
    j->rc = -1;
    /* reset IV so GHASH state is clean; IV content irrelevant for our use */
    CRYPTO_gcm128_setiv(j->gctx, zeroes, 12);
    if(CRYPTO_gcm128_aad(j->gctx, j->data, j->len) != 0) return NULL;
    CRYPTO_gcm128_tag(j->gctx, j->hash, 16);
    j->rc = 0;
    return NULL;
}

/* Multiply two GF(2^128) elements (big-endian, GCM bit ordering) : out = x*y.
   Used only for the small reduction of per-chunk hashes, so a simple
   bit-by-bit implementation is fine. */
static void gf_mul(unsigned char out[16], const unsigned char x[16], const unsigned char y[16]){
    unsigned char v[16], z[16];
    memcpy(v, x, 16);
    memset(z, 0, 16);
    for(int i=0;i<16;i++){
        for(int b=7;b>=0;b--){
            unsigned char mask = -((y[i] >> b) & 1); /* 0xFF or 0x00 */
            for(int k=0;k<16;k++) z[k] ^= v[k] & mask;
            /* v = v * x (right shift in GCM bit ordering, reduce with R) */
            unsigned char lsb = v[15] & 1;
            for(int k=15;k>0;k--) v[k] = (v[k] >> 1) | (v[k-1] << 7);
            v[0] >>= 1;
            if(lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(out, z, 16);
}

static void gf_pow(unsigned char out[16], const unsigned char h[16], uint64_t exp){
    unsigned char base[16], result[16];
    memcpy(base, h, 16);
    memset(result, 0, 16); result[15] = 1; /* one */
    while(exp){
        if(exp & 1){
            unsigned char tmp[16];
            gf_mul(tmp, result, base);
            memcpy(result, tmp, 16);
        }
        unsigned char tmp[16];
        gf_mul(tmp, base, base);
        memcpy(base, tmp, 16);
        exp >>= 1;
    }
    memcpy(out, result, 16);
}

static void xor16(unsigned char *a, const unsigned char *b){
    for(int i=0;i<16;i++) a[i] ^= b[i];
}

/* Module state: reusable contexts keyed... we keep a small cache keyed by the
   raw key bytes, rebuilt when the key changes. */
typedef struct {
    unsigned char key[32];
    int keylen;
    EVP_CIPHER_CTX *ctr[NTHREADS];
    GCM128_CONTEXT *ghash[NTHREADS];
    unsigned char H[16];
    int ready;
} cache_t;

static cache_t CACHE;

static void cache_clear(void){
    for(int i=0;i<NTHREADS;i++){
        if(CACHE.ctr[i]){ EVP_CIPHER_CTX_free(CACHE.ctr[i]); CACHE.ctr[i]=NULL; }
        if(CACHE.ghash[i]){ CRYPTO_gcm128_release(CACHE.ghash[i]); CACHE.ghash[i]=NULL; }
    }
    CACHE.ready = 0;
}

static int cache_setup(const unsigned char *key, int keylen){
    if(CACHE.ready && CACHE.keylen==keylen && memcmp(CACHE.key, key, keylen)==0) return 1;
    cache_clear();
    const EVP_CIPHER *ciph = keylen==16? EVP_aes_128_ecb() : keylen==24? EVP_aes_192_ecb() : EVP_aes_256_ecb();
    for(int i=0;i<NTHREADS;i++){
        CACHE.ctr[i] = EVP_CIPHER_CTX_new();
        if(!CACHE.ctr[i]) return 0;
        if(EVP_EncryptInit_ex(CACHE.ctr[i], ciph, NULL, key, NULL)!=1) return 0;
    }
    /* H = AES_K(0) via one CTR ctx */
    unsigned char zeroes[16]; memset(zeroes, 0, 16);
    int outlen=0;
    unsigned char H[16];
    EVP_CIPHER_CTX *ectx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ectx, ciph, NULL, key, NULL);
    EVP_EncryptUpdate(ectx, H, &outlen, zeroes, 16);
    EVP_CIPHER_CTX_free(ectx);
    memcpy(CACHE.H, H, 16);

    /* GCM contexts with the same key, for GHASH via AAD path */
    for(int i=0;i<NTHREADS;i++){
        /* Use CRYPTO_gcm128 with AES block function from EVP? We need a block128_f.
           Instead, build GCM context using EVP? CRYPTO_gcm128_new needs block128_f.
           We'll supply one based on EVP_EncryptUpdate of a dedicated ECB ctx. */
    }
    memcpy(CACHE.key, key, keylen);
    CACHE.keylen = keylen;
    CACHE.ready = 1;
    return 1;
}

/* block function for CRYPTO_gcm128 using a thread-local EVP ctx is awkward.
   Provide a plain AES block via EVP_aes and a static key schedule using the
   low-level AES_set_encrypt_key / AES_encrypt, which on this OpenSSL uses
   AES-NI for the block function. GHASH itself is the bottleneck candidate;
   we mainly need correctness of H, which we compute with EVP. For GHASH we
   use CRYPTO_gcm128 with AES_encrypt block fn. */
#include <openssl/aes.h>

static void aes_block(const unsigned char *in, unsigned char *out, const void *k){
    AES_encrypt(in, out, (const AES_KEY*)k);
}

typedef struct {
    AES_KEY aes;
    GCM128_CONTEXT *g[NTHREADS];
    unsigned char key[32];
    int keylen;
    int ready;
} gcache_t;
static gcache_t GCACHE;

static int gcache_setup(const unsigned char *key, int keylen){
    if(GCACHE.ready && GCACHE.keylen==keylen && memcmp(GCACHE.key, key, keylen)==0) return 1;
    for(int i=0;i<NTHREADS;i++) if(GCACHE.g[i]){ CRYPTO_gcm128_release(GCACHE.g[i]); GCACHE.g[i]=NULL; }
    if(AES_set_encrypt_key(key, keylen*8, &GCACHE.aes)!=0) return 0;
    for(int i=0;i<NTHREADS;i++){
        GCACHE.g[i] = CRYPTO_gcm128_new(&GCACHE.aes, (block128_f)aes_block);
        if(!GCACHE.g[i]) return 0;
    }
    memcpy(GCACHE.key, key, keylen);
    GCACHE.keylen = keylen;
    GCACHE.ready = 1;
    return 1;
}

static PyObject *gcm_encrypt(PyObject *self, PyObject *args){
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    int has_aad = 0;
    if(!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)){
        PyErr_Clear();
        if(!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    } else has_aad = 1;
    if((key.len!=16 && key.len!=24 && key.len!=32)){
        PyErr_SetString(PyExc_ValueError, "bad key"); goto fail_early;
    }

    PyObject *ctobj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tagobj = PyBytes_FromStringAndSize(NULL, 16);
    if(!ctobj || !tagobj){ PyErr_NoMemory(); goto fail_early; }
    unsigned char *ct = (unsigned char*)PyBytes_AS_STRING(ctobj);
    unsigned char *tag = (unsigned char*)PyBytes_AS_STRING(tagobj);

    if(!cache_setup(key.buf, (int)key.len) || !gcache_setup(key.buf, (int)key.len)){
        PyErr_SetString(PyExc_RuntimeError, "setup failed"); goto fail;
    }

    /* J0 */
    unsigned char J0[16];
    if(nonce.len == 12){
        memcpy(J0, nonce.buf, 12);
        J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    } else {
        /* GHASH the nonce into J0 */
        unsigned char zeroes[16]; memset(zeroes,0,16);
        CRYPTO_gcm128_setiv(GCACHE.g[0], zeroes, 12);
        size_t nlen = nonce.len;
        size_t pad = (16 - (nlen % 16)) % 16;
        unsigned char *buf = malloc(nlen + pad + 16);
        memcpy(buf, nonce.buf, nlen);
        memset(buf+nlen, 0, pad+16);
        uint64_t bits = (uint64_t)nlen * 8;
        for(int i=0;i<8;i++) buf[nlen+pad+8+i] = (unsigned char)(bits >> (56-8*i));
        CRYPTO_gcm128_aad(GCACHE.g[0], buf, nlen+pad+16);
        CRYPTO_gcm128_tag(GCACHE.g[0], J0, 16);
        free(buf);
    }

    size_t total = pt.len;
    size_t full = total & ~(size_t)15;
    size_t tail = total - full;
    int nth = (full >= 1024*1024) ? NTHREADS : 1;

    /* ---- CTR in parallel ---- */
    ctr_job cjobs[NTHREADS];
    pthread_t cth[NTHREADS];
    size_t blocks = full/16;
    size_t bper = blocks/nth;
    size_t assigned = 0;
    int claunched = 0;
    for(int i=0;i<nth;i++){
        size_t b = (i==nth-1)? blocks-assigned : bper;
        size_t off = assigned*16;
        cjobs[i].ctx = CACHE.ctr[i];
        cjobs[i].in = (unsigned char*)pt.buf + off;
        cjobs[i].out = ct + off;
        cjobs[i].len = b*16;
        /* counter for first block of this chunk = assigned+1 (inc32 of J0) */
        uint32_t ctr = (uint32_t)(assigned + 1);
        memcpy(cjobs[i].iv, J0, 12);
        uint32_t c0 = ((uint32_t)J0[12]<<24)|((uint32_t)J0[13]<<16)|((uint32_t)J0[14]<<8)|J0[15];
        uint32_t c = c0 + ctr;
        cjobs[i].iv[12]=c>>24; cjobs[i].iv[13]=c>>16; cjobs[i].iv[14]=c>>8; cjobs[i].iv[15]=c;
        cjobs[i].rc = 0;
        if(nth==1) ctr_worker(&cjobs[0]);
        else pthread_create(&cth[i], NULL, ctr_worker, &cjobs[i]);
        assigned += b;
        claunched++;
    }
    /* tail block */
    if(tail){
        unsigned char block[16]; memset(block, 0, 16);
        memcpy(block, (unsigned char*)pt.buf + full, tail);
        unsigned char ks[16];
        uint32_t c0 = ((uint32_t)J0[12]<<24)|((uint32_t)J0[13]<<16)|((uint32_t)J0[14]<<8)|J0[15];
        uint32_t c = c0 + (uint32_t)(blocks + 1);
        unsigned char iv[16]; memcpy(iv, J0, 12);
        iv[12]=c>>24; iv[13]=c>>16; iv[14]=c>>8; iv[15]=c;
        int outlen=0;
        EVP_EncryptInit_ex(CACHE.ctr[0], NULL, NULL, NULL, iv);
        EVP_EncryptUpdate(CACHE.ctr[0], ks, &outlen, block, 16);
        for(size_t i=0;i<tail;i++) ct[full+i] = ((unsigned char*)pt.buf)[full+i] ^ ks[i];
    }
    if(nth>1) for(int i=0;i<claunched;i++) pthread_join(cth[i], NULL);
    for(int i=0;i<claunched;i++) if(cjobs[i].rc){ PyErr_SetString(PyExc_RuntimeError,"ctr"); goto fail; }

    /* ---- GHASH in parallel over ciphertext chunks (plus AAD on chunk 0) ----
       We compute per-chunk GHASH treating each chunk as AAD (so it's pure
       GHASH of that byte string), then combine with powers of H. */
    ghash_job gjobs[NTHREADS];
    pthread_t gth[NTHREADS];
    size_t lengths[NTHREADS];
    int glaunched = 0;
    assigned = 0;
    for(int i=0;i<nth;i++){
        size_t b = (i==nth-1)? blocks-assigned : bper;
        size_t off = assigned*16;
        size_t len = b*16 + ((i==nth-1)? tail : 0);
        lengths[i] = len;
        gjobs[i].gctx = GCACHE.g[i];
        gjobs[i].data = ct + off;
        gjobs[i].len = len;
        gjobs[i].rc = 0;
        if(len==0){ memset(gjobs[i].hash, 0, 16); }
        else if(nth==1) ghash_worker(&gjobs[0]);
        else pthread_create(&gth[i], NULL, ghash_worker, &gjobs[i]);
        assigned += b;
        glaunched++;
    }
    if(nth>1) for(int i=0;i<glaunched;i++) if(lengths[i]) pthread_join(gth[i], NULL);

    /* AAD hash */
    unsigned char aad_hash[16]; memset(aad_hash, 0, 16);
    if(has_aad && aad.len){
        unsigned char zeroes[16]; memset(zeroes,0,16);
        CRYPTO_gcm128_setiv(GCACHE.g[0], zeroes, 12);
        size_t alen = aad.len;
        size_t pad = (16-(alen%16))%16;
        unsigned char *buf = malloc(alen+pad);
        memcpy(buf, aad.buf, alen); memset(buf+alen, 0, pad);
        CRYPTO_gcm128_aad(GCACHE.g[0], buf, alen+pad);
        CRYPTO_gcm128_tag(GCACHE.g[0], aad_hash, 16);
        free(buf);
    }

    /* Combine chunk hashes: S = aad_hash*H^(ceil(clen/16)+ceil? no)
       Standard: GHASH = (AAD_padded || C_padded || lenblock)
       AAD occupies na = ceil(aad_len/16) blocks, C occupies nc = ceil(total/16)
       blocks, then one length block.
       chunk i covers blocks [start_i, start_i+nb_i) of the ciphertext portion,
       which sits nb_before blocks after the AAD portion.
       Contribution of chunk i = GHASH(chunk_i_padded) * H^(nc - end_i + 1)
       where +1 accounts for the length block that follows everything.
       aad contribution = aad_hash * H^(nc + 1).
    */
    size_t nc = (total + 15)/16;
    unsigned char S[16]; memset(S, 0, 16);
    if(has_aad && aad.len){
        size_t na_blocks_after = nc + 1; /* length block + ciphertext blocks */
        unsigned char pwr[16];
        gf_pow(pwr, CACHE.H, na_blocks_after);
        unsigned char contrib[16];
        gf_mul(contrib, aad_hash, pwr);
        xor16(S, contrib);
    }
    size_t end = 0;
    for(int i=0;i<glaunched;i++){
        size_t nb = (lengths[i]+15)/16;
        end += nb;
        if(nb==0) continue;
        if(gjobs[i].rc){ PyErr_SetString(PyExc_RuntimeError,"ghash"); goto fail; }
        uint64_t exp = (nc - end) + 1; /* blocks after this chunk, incl length */
        unsigned char pwr[16], contrib[16];
        gf_pow(pwr, CACHE.H, exp);
        gf_mul(contrib, gjobs[i].hash, pwr);
        xor16(S, contrib);
    }
    /* length block */
    unsigned char lenblock[16]; memset(lenblock, 0, 16);
    uint64_t abits = (has_aad? (uint64_t)aad.len : 0) * 8;
    uint64_t cbits = (uint64_t)total * 8;
    for(int i=0;i<8;i++){ lenblock[i] = (unsigned char)(abits >> (56-8*i)); lenblock[8+i] = (unsigned char)(cbits >> (56-8*i)); }
    xor16(S, lenblock);
    unsigned char final_hash[16];
    gf_mul(final_hash, S, CACHE.H);

    /* tag = final_hash XOR E(K, J0) */
    unsigned char ek[16]; int outlen=0;
    EVP_EncryptInit_ex(CACHE.ctr[0], NULL, NULL, NULL, J0);
    unsigned char z[16]; memset(z,0,16);
    EVP_EncryptUpdate(CACHE.ctr[0], ek, &outlen, z, 16);
    for(int i=0;i<16;i++) tag[i] = final_hash[i] ^ ek[i];

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ctobj, tagobj);

fail:
    Py_XDECREF(ctobj); Py_XDECREF(tagobj);
fail_early:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return NULL;
}

