    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moddef = {PyModuleDef_HEAD_INIT, "gcmfast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_gcmfast(void){ return PyModule_Create(&moddef); }
