/*
 * Parallel AES-GCM.
 *
 * CTR encryption and GHASH are split across NTHREADS cores. GHASH chunks are
 * combined with H^k computed by square-and-multiply, so the result is exactly
 * the single-threaded GCM tag. Contexts are cached and reused across calls.
 */
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

#define NTHREADS 4
#define MIN_PARALLEL (256*1024)

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned char iv[16];
    int rc;
} ctr_job;

static void *ctr_worker(void *arg){
    ctr_job *j = arg;
    int outlen = 0;
    j->rc = -1;
    if(EVP_EncryptInit_ex(j->ctx, NULL, NULL, NULL, j->iv) != 1) return NULL;
    if(j->len && EVP_EncryptUpdate(j->ctx, j->out, &outlen, j->in, (int)j->len) != 1) return NULL;
    j->rc = 0;
    return NULL;
}

/* ---------- GF(2^128) with GCM's bit ordering, R = 0xe1 ---------- */

static void gf_mul(uint8_t out[16], const uint8_t x[16], const uint8_t y[16]){
    uint8_t v[16], z[16];
    memcpy(v, x, 16);
    memset(z, 0, 16);
    for(int i=0;i<16;i++){
        uint8_t byte = y[i];
        for(int b=0;b<8;b++){
            if(byte & 0x80){
