            for(int k=15;k>0;k--) v[k] = (uint8_t)((v[k] >> 1) | (v[k-1] << 7));
            v[0] >>= 1;
            if(lsb) v[0] ^= 0xe1;
            byte <<= 1;
        }
    }
    memcpy(out, z, 16);
}

static void xor16(uint8_t *a, const uint8_t *b){
    for(int i=0;i<16;i++) a[i] ^= b[i];
}

/* ---------- cached per-key state ---------- */

typedef struct {
    uint8_t key[32];
    int keylen;
    EVP_CIPHER_CTX *ctr[NTHREADS];
    const EVP_CIPHER *ctr_ciph;
    const EVP_CIPHER *ecb_ciph;
    uint8_t H[16];
    int ready;
} cache_t;

static cache_t CACHE;

static void cache_clear(void){
    for(int i=0;i<NTHREADS;i++){
        if(CACHE.ctr[i]){ EVP_CIPHER_CTX_free(CACHE.ctr[i]); CACHE.ctr[i]=NULL; }
    }
    CACHE.ready = 0;
}

static int cache_setup(const uint8_t *key, int keylen){
    if(CACHE.ready && CACHE.keylen==keylen && memcmp(CACHE.key, key, keylen)==0) return 1;
    cache_clear();
    switch(keylen){
        case 16: CACHE.ctr_ciph = EVP_aes_128_ctr(); CACHE.ecb_ciph = EVP_aes_128_ecb(); break;
        case 24: CACHE.ctr_ciph = EVP_aes_192_ctr(); CACHE.ecb_ciph = EVP_aes_192_ecb(); break;
        case 32: CACHE.ctr_ciph = EVP_aes_256_ctr(); CACHE.ecb_ciph = EVP_aes_256_ecb(); break;
        default: return 0;
    }
    for(int i=0;i<NTHREADS;i++){
        CACHE.ctr[i] = EVP_CIPHER_CTX_new();
        if(!CACHE.ctr[i]) return 0;
        if(EVP_EncryptInit_ex(CACHE.ctr[i], CACHE.ctr_ciph, NULL, key, NULL)!=1) return 0;
    }
    /* H = AES_K(0^128) */
    EVP_CIPHER_CTX *ectx = EVP_CIPHER_CTX_new();
    uint8_t zeroes[16]; memset(zeroes, 0, 16);
    int outlen=0;
    if(EVP_EncryptInit_ex(ectx, CACHE.ecb_ciph, NULL, key, NULL)!=1) return 0;
    if(EVP_EncryptUpdate(ectx, CACHE.H, &outlen, zeroes, 16)!=1) return 0;
    EVP_CIPHER_CTX_free(ectx);
    memcpy(CACHE.key, key, keylen);
    CACHE.keylen = keylen;
    CACHE.ready = 1;
    return 1;
}

/* GHASH of an arbitrary-length byte string (padded with zeros to 16). */
static void ghash_bytes(uint8_t out[16], const uint8_t *data, size_t len){
    uint8_t y[16]; memset(y, 0, 16);
    size_t full = len & ~(size_t)15;
    for(size_t i=0;i<full;i+=16){
        xor16(y, data+i);
        uint8_t tmp[16]; gf_mul(tmp, y, CACHE.H); memcpy(y, tmp, 16);
    }
    if(len & 15){
        uint8_t blk[16]; memset(blk, 0, 16);
        memcpy(blk, data+full, len-full);
        xor16(y, blk);
        uint8_t tmp[16]; gf_mul(tmp, y, CACHE.H); memcpy(y, tmp, 16);
    }
    memcpy(out, y, 16);
}

typedef struct {
    const uint8_t *data;
    size_t len;
    uint8_t hash[16];
} ghash_job;

static void *ghash_worker(void *arg){
    ghash_job *j = arg;
    ghash_bytes(j->hash, j->data, j->len);
    return NULL;
}

static void gf_pow(uint8_t out[16], uint64_t exp){
    uint8_t base[16], result[16];
    memcpy(base, CACHE.H, 16);
    memset(result, 0, 16); result[15] = 1;
    while(exp){
        if(exp & 1){ uint8_t t[16]; gf_mul(t, result, base); memcpy(result, t, 16); }
        uint8_t t[16]; gf_mul(t, base, base); memcpy(base, t, 16);
        exp >>= 1;
    }
    memcpy(out, result, 16);
}

static void store64(uint8_t *p, uint64_t v){
    for(int i=7;i>=0;i--){ p[i] = (uint8_t)v; v >>= 8; }
}

static PyObject *gcm_encrypt(PyObject *self, PyObject *args){
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    int has_aad = 0;
    if(!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)){
        PyErr_Clear();
        if(!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    } else has_aad = 1;

    if(key.len!=16 && key.len!=24 && key.len!=32){
        PyErr_SetString(PyExc_ValueError, "invalid key size"); goto early;
    }
    if(!cache_setup(key.buf, (int)key.len)){
        PyErr_SetString(PyExc_RuntimeError, "setup failed"); goto early;
    }

    PyObject *ctobj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tagobj = PyBytes_FromStringAndSize(NULL, 16);
    if(!ctobj || !tagobj){ PyErr_NoMemory(); goto early; }
    uint8_t *ct = (uint8_t*)PyBytes_AS_STRING(ctobj);
    uint8_t *tag = (uint8_t*)PyBytes_AS_STRING(tagobj);

    /* J0 */
    uint8_t J0[16];
    if(nonce.len == 12){
        memcpy(J0, nonce.buf, 12);
        J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    } else {
        size_t nlen = nonce.len;
        size_t pad = (16 - (nlen % 16)) % 16;
        uint8_t *buf = malloc(nlen + pad + 16);
        memcpy(buf, nonce.buf, nlen);
        memset(buf+nlen, 0, pad+16);
        store64(buf+nlen+pad+8, (uint64_t)nlen*8);
        ghash_bytes(J0, buf, nlen+pad+16);
        free(buf);
    }

    size_t total = (size_t)pt.len;
    size_t full = total & ~(size_t)15;
    size_t tail = total - full;
    int nth = (full >= MIN_PARALLEL) ? NTHREADS : 1;
    size_t blocks = full/16;
    size_t bper = nth ? blocks/nth : 0;

    /* ---- parallel CTR ---- */
    ctr_job cjobs[NTHREADS];
    pthread_t cth[NTHREADS];
    size_t assigned = 0;
    int claunched = 0;
    uint32_t c0 = ((uint32_t)J0[12]<<24)|((uint32_t)J0[13]<<16)|((uint32_t)J0[14]<<8)|J0[15];
    for(int i=0;i<nth;i++){
        size_t b = (i==nth-1) ? blocks-assigned : bper;
        size_t off = assigned*16;
        cjobs[i].ctx = CACHE.ctr[i];
        cjobs[i].in = (uint8_t*)pt.buf + off;
        cjobs[i].out = ct + off;
        cjobs[i].len = b*16;
        uint32_t ctr = c0 + (uint32_t)(assigned + 1); /* data starts at inc32(J0) */
        memcpy(cjobs[i].iv, J0, 12);
        cjobs[i].iv[12]=ctr>>24; cjobs[i].iv[13]=ctr>>16; cjobs[i].iv[14]=ctr>>8; cjobs[i].iv[15]=ctr;
        if(nth==1) ctr_worker(&cjobs[0]);
        else pthread_create(&cth[i], NULL, ctr_worker, &cjobs[i]);
        assigned += b;
        claunched++;
    }
    if(tail){
        uint8_t block[16]; memset(block, 0, 16);
        memcpy(block, (uint8_t*)pt.buf+full, tail);
        uint8_t ks[16];
        uint32_t ctr = c0 + (uint32_t)(blocks + 1);
        uint8_t iv[16]; memcpy(iv, J0, 12);
        iv[12]=ctr>>24; iv[13]=ctr>>16; iv[14]=ctr>>8; iv[15]=ctr;
        int outlen=0;
        EVP_EncryptInit_ex(CACHE.ctr[0], NULL, NULL, NULL, iv);
        EVP_EncryptUpdate(CACHE.ctr[0], ks, &outlen, block, 16);
        for(size_t i=0;i<tail;i++) ct[full+i] = ((uint8_t*)pt.buf)[full+i] ^ ks[i];
    }
    if(nth>1) for(int i=0;i<claunched;i++) pthread_join(cth[i], NULL);
    for(int i=0;i<claunched;i++){
        if(cjobs[i].rc){ PyErr_SetString(PyExc_RuntimeError, "ctr failed"); goto fail; }
    }

    /* ---- GHASH ---- */
    uint8_t S[16]; memset(S, 0, 16);

    if(has_aad && aad.len){
        uint8_t ah[16];
        ghash_bytes(ah, aad.buf, aad.len);
        xor16(S, ah);
    }

    if(nth==1){
        uint8_t ch[16];
        ghash_bytes(ch, ct, total);
        xor16(S, ch);
    } else {
        /* per-chunk GHASH, then fold with powers of H */
        ghash_job gjobs[NTHREADS];
        pthread_t gth[NTHREADS];
        size_t lengths[NTHREADS];
        size_t nb_chunks[NTHREADS];
        assigned = 0;
        int glaunched = 0;
        for(int i=0;i<nth;i++){
            size_t b = (i==nth-1)? blocks-assigned : bper;
            size_t off = assigned*16;
            size_t len = b*16 + ((i==nth-1)? tail : 0);
            lengths[i] = len;
            nb_chunks[i] = (len+15)/16;
            gjobs[i].data = ct+off;
            gjobs[i].len = len;
            if(len) pthread_create(&gth[i], NULL, ghash_worker, &gjobs[i]);
            else memset(gjobs[i].hash, 0, 16);
            assigned += b;
            glaunched++;
        }
        for(int i=0;i<glaunched;i++) if(lengths[i]) pthread_join(gth[i], NULL);

        size_t nc = (total+15)/16;
        size_t end = 0;
        for(int i=0;i<glaunched;i++){
            size_t nb = nb_chunks[i];
            end += nb;
            if(!nb) continue;
            /* chunk hash already includes its internal H multiplications and
               equals GHASH(chunk). It must be shifted by H^(blocks after it). */
            uint64_t exp = nc - end;
            if(exp){
                uint8_t pwr[16], contrib[16];
                gf_pow(pwr, exp);
                gf_mul(contrib, gjobs[i].hash, pwr);
                xor16(S, contrib);
            } else {
                xor16(S, gjobs[i].hash);
            }
        }
    }

    /* length block */
    uint8_t lenblock[16];
    store64(lenblock, (has_aad?(uint64_t)aad.len:0)*8);
    store64(lenblock+8, (uint64_t)total*8);
    xor16(S, lenblock);
    uint8_t final_hash[16];
    gf_mul(final_hash, S, CACHE.H);

    /* tag mask = AES_K(J0) = CTR encrypt of one zero block with iv J0 */
    uint8_t ek[16], z[16]; memset(z, 0, 16);
    int outlen=0;
    EVP_EncryptInit_ex(CACHE.ctr[0], NULL, NULL, NULL, J0);
    EVP_EncryptUpdate(CACHE.ctr[0], ek, &outlen, z, 16);
    for(int i=0;i<16;i++) tag[i] = final_hash[i] ^ ek[i];

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ctobj, tagobj);

fail:
    Py_XDECREF(ctobj); Py_XDECREF(tagobj);
early:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if(has_aad) PyBuffer_Release(&aad);
    return NULL;
}

